## Why This Is Asked

This question tests mastery of rope-like data structures for dynamic sequences with cut-paste operations while maintaining fast range queries.

## Key Concepts

- **Implicit treap / rope**: Uses position as the key rather than explicit values
- **Split and merge operations**: Fundamental primitives for manipulating segments
- **Augmented data**: size and range sum maintained at each node
- **Edge cases**: Properly handling when dest overlaps with [l, r]

## Code Example

```javascript
class Node {
  constructor(v) {
    this.v = v;
    this.pr = Math.random();
    this.l = this.r = null;
    this.sz = 1;
    this.sum = v;
  }
}

function upd(t) {
  if (!t) return;
  t.sz = 1 + sz(t.l) + sz(t.r);
  t.sum = t.v + sum(t.l) + sum(t.r);
}

function split(t, k, l, r) {
  if (!t) return [null, null];
  if (sz(t.l) >= k) {
    let [a, b] = split(t.l, k, l, r);
    t.l = b; upd(t);
    return [a, t];
  } else {
    let [a, b] = split(t.r, k - sz(t.l) - 1, l, r);
    t.r = a; upd(t);
    return [t, b];
  }
}

function merge(a, b) {
  if (!a || !b) return a || b;
  if (a.pr < b.pr) {
    a.r = merge(a.r, b); upd(a); return a;
  } else {
    b.l = merge(a, b.l); upd(b); return b;
  }
}

function rangeSum(t, l, r) {
  let [a, bc] = split(t, l);
  let [b, c] = split(bc, r - l + 1);
  let res = sum(b);
  t = merge(a, merge(b, c));
  return res;
}

function moveSegment(t, l, r, dest) {
  let len = r - l + 1;
  let [a, bc] = split(t, l);
  let [b, c] = split(bc, len);
  t = merge(a, c);

  let pos = dest <= l ? dest : dest - len;
  let [x, y] = split(t, pos);\n  return merge(merge(x, b), y);
}
```

## Why This Is Asked
Tests ability to design a dynamic string structure supporting weighted, prefix-based queries and order-statistics. A Trie augmented with per-node aggregates enables efficient prefix sums and k-th retrieval while handling duplicates via cumulative weights.

## Key Concepts
- Trie with per-node aggregates (subtreeWeight, terminalWeight)
- O(len(word)) time complexity for insert/erase operations
- O(len(prefix)) for prefix-sum queries
- O(len(prefix) + len(target_word)) for kth-word queries
- Duplicate handling via cumulative weight values

## Code Example
```javascript
class WeightedTrie {
  constructor() {
    this.root = new TrieNode();
  }

  insertWord(word, w) {
    let node = this.root;
    for (const char of word) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.children[idx]) node.children[idx] = new TrieNode();
      node = node.children[idx];
      node.subtreeWeight += w;
    }
    node.terminalWeight += w;
  }

  eraseWord(word, w) {
    this.insertWord(word, -w);
  }

  queryPrefixSum(prefix) {
    let node = this.traverse(prefix);
    return node ? node.subtreeWeight : 0;
  }

  kthWordWithPrefix(prefix, k) {
    let node = this.traverse(prefix);
    if (!node || node.subtreeWeight < k) return null;
    let word = prefix;
    while (!node.terminalWeight) {
      for (let i = 0; i < 26; i++) {
        if (!node.children[i]) continue;
        if (node.children[i].subtreeWeight >= k) {
          word += String.fromCharCode(97 + i);
          node = node.children[i];
          break;
        }
        k -= node.children[i].subtreeWeight;
      }
    }
    return word;
  }

  traverse(prefix) {
    let node = this.root;
    for (const char of prefix) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.children[idx]) return null;
      node = node.children[idx];
    }
    return node;
  }
}

class TrieNode {
  constructor() {
    this.children = new Array(26).fill(null);
    this.subtreeWeight = 0;
    this.terminalWeight = 0;
  }
}
```

